258	function isIntegerIn(value, min, max) {
259	  return typeof value === 'number' && Number.isInteger(value) && value >= min && value <= max;
260	}
261	
262	// An action node either keeps the legacy `message` behavior or names a
263	// business operation the caller supplies at run time. The retry block is
264	// either absent (one attempt, no waiting) or present with all four
265	// parameters together.
266	function compileAction(node) {
267	  let name = null;
268	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
269	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
270	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
271	    }
272	    name = node.operation;
273	  }
274	
275	  const retry = { attempts: 1, initialDelayMs: 0, backoffFactor: 1, maxDelayMs: 0 };
276	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
277	    if (!name) {
278	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
279	    }
280	    const config = node.retry;
281	    if (!isUsableObject(config)) {
282	      throw new Error(`action node ${node.id}: retry must be an object`);
283	    }
284	    const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
285	    if (missing.length > 0) {
286	      throw new Error(`action node ${node.id}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
287	    }
288	    if (!isIntegerIn(config.attempts, 1, 10)) {
289	      throw new Error(`action node ${node.id}: retry.attempts must be an integer between 1 and 10`);
290	    }
291	    if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
292	      throw new Error(`action node ${node.id}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
293	    }
294	    if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
295	      throw new Error(`action node ${node.id}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
296	    }
297	    if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
298	      || config.backoffFactor < 1 || config.backoffFactor > 4) {
299	      throw new Error(`action node ${node.id}: retry.backoffFactor must be a finite number between 1 and 4`);
300	    }
301	    if (config.maxDelayMs < config.initialDelayMs) {
302	      throw new Error(`action node ${node.id}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
303	    }
304	    retry.attempts = config.attempts;
305	    retry.initialDelayMs = config.initialDelayMs;
