node --input-type=module -e "
import { executeWorkflowAsync, executeWorkflow } from './src/engine.js';

const wf = {
  id: 'demo', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'charge' },
    { id: 'charge', type: 'action', operation: 'charge', retry: { attempts: 3, initialDelayMs: 10, backoffFactor: 2, maxDelayMs: 25 }, next: 'done' },
    { id: 'done', type: 'end', result: 'ok' },
  ],
};

const r = await executeWorkflowAsync(wf, { amount: 100 }, {
  charge: (input, output, nodeId, attempt) => {
    if (attempt < 3) throw new Error('declined #' + attempt);
    return { charged: input.amount, attempt };
  },
});
console.log(JSON.stringify(r, null, 2));

// sync refusal
try { executeWorkflow(wf, {}); } catch (e) { console.log('SYNC REFUSAL:', e.message); }
"

